{"implementation": "def solve(case):
    text = case["text"]
    max_rounds = case["max_rounds"]
    passes = case["passes"]
    applications = []
    fixed_point = False
    for _ in range(max_rounds):
        changed = False
        for p in passes:
            old = p["old"]
            new = p["new"]
            if old in text:
                text = text.replace(old, new)
                applications.append(p["name"])
                changed = True
        if not changed:
            fixed_point = True
            break
    return {
        "applications": applications,
        "fixed_point": fixed_point,
        "text": text
    }"}
